        t["NOTE-OUT"]["in:velocity"] = LearnEntry{"Velocidad (0-1) — capturada en el instante en que el gate se activa; sin cable, 1,0.", "", ""};
        t["NOTE-OUT"]["in:accent"] = LearnEntry{"Acento — capturado en el instante en que el gate se activa.", "", ""};
