        t["ADDITIVE"]["tilt"] = LearnEntry{"Brightness — the tilt of the spectrum. 0 = dark (the harmonics fall off fast, ~k^-2.6); 1 = almost flat (all 64 partials strong).", "It is the opposite of a filter: instead of cutting the treble, you choose how much energy each partial gets as it is built.", "Patch ENVELOPE.env → TILT: the timbre opens its brightness along with the note."};
        t["ADDITIVE"]["comb"] = LearnEntry{"Spectral comb: it digs valleys into the spectrum. 0 = flat; 1 = 12 teeth, deep valleys — a coarse formant or a comb-filter effect, without filtering anything.", "g_k = (1−comb) + comb·(0.5 + 0.5·cos(2π·teeth·k/64)), teeth = 1 + 11·comb.", ""};
        t["ADDITIVE"]["odd"] = LearnEntry{"Odd/even balance of the partials. 0 = the full series; +1 = odd only (square, clarinet, bright and hollow); −1 = even only (an octave up, a nasal sound).", "", ""};
        t["ADDITIVE"]["stretch"] = LearnEntry{"Inharmonicity — it stretches or compresses the partials. 0 = harmonic (ratio k); +1 = stretched (a bell, metal, the piano's treble); −1 = compressed (partials close together, dense beating).", "ratio_k = k + stretch·0.004·k·(k−1) — the effect is quadratic: almost nothing on the first partials, strong on the upper ones.", "Modulate STRCH with a slow LFO: the sound turns metallic and comes back."};
        t["ADDITIVE"]["drift"] = LearnEntry{"Shimmer — each partial gets a micro-detune and an amplitude breathing from slow sinusoids. 0 = deterministic.", "No RNG: it is the sum of incommensurable sinusoids, so the path does not repeat but the render is reproducible.", ""};
        t["ADDITIVE"]["fm_amount"] = LearnEntry{"Depth of the linear FM from the FM input.", "", ""};
