        t["OPERATOR"]["algo"] = LearnEntry{"Which operator modulates which — 8 algorithms, from 0 (A→B→C→D, the most 'FM') to 7 (A,B,C,D in parallel, additive/organ).", "The order is always A→B→C→D and only A has feedback, so there is no loop between operators — the calculation is a single pass.", "Start at 0 with a medium INDEX and turn ALGO slowly: the spectrum reorganises itself at each step."};
        t["OPERATOR"]["index"] = LearnEntry{"Global modulation depth. 0 = the 4 operators are pure sinusoids; 1 ≈ 6 cycles of phase deviation (very bright).", "In FM, the index controls how many sidebands appear and how strongly (Chowning's Bessel functions).", "Patch ENVELOPE.env → IDX: the bright attack that darkens into the tail — the 'DX sound'."};
        t["OPERATOR"]["feedback"] = LearnEntry{"Operator A modulates its own phase (the average of the last 2 samples, DX7-style).", "On its own it already takes A's sinusoid to a sawtooth — a source of harmonics with no need for another operator.", ""};
        t["OPERATOR"]["ratio_b"] = LearnEntry{"Frequency ratio of operator B relative to A, QUANTISED: 0.5 / 1 / 1.5 / 2 / 2.5 / 3 / 4 / 5 / 7 / 9.", "A whole number = harmonic (a musical timbre); a fraction (2.5) = inharmonic (a bell, metal). It is the pitch QUANTIZER, but for timbre.", ""};
