        t["PULSAR"]["freq"] = LearnEntry{"Repetition rate of the pulsarets = the PITCH (20–2000 Hz, +1 V/oct CV). Each firing launches a grain; the silence between them is what defines the note.", "Pulsar synthesis (Curtis Roads): a train of pulsarets — a short grain + silence, total period p. freq = 1/p.", "SEQUENCE.pitch → PIT: a melody. Lower it to ~30 Hz and each pulsaret becomes a separate event (rhythm)."};
        t["PULSAR"]["formant"] = LearnEntry{"Internal frequency of the pulsaret = the TIMBRE, INDEPENDENT of the pitch (0.1–8×, +CV). Low = hollow/formantic; high = bright/nasal. It does NOT detune.", "It is the second frequency of pulsar synthesis: formant = 1/d (d = duration of the pulsaret). The harmonic comb stays at multiples of freq; formant only moves the spectral ENVELOPE.", "LFO → FQM: a 'wah' with no filter. At formant≈1 the pulsaret fills the whole period (100 % duty)."};
        t["PULSAR"]["shape"] = LearnEntry{"Shape of the pulsaret: 0 = 1 cycle of a sine; up to 1 = 2–3 cycles + a high harmonic (a narrower, richer pulse).", "", ""};
