        t["PULSAR"]["jitter"] = LearnEntry{"SEEDED Rasgo deviation in each pulsaret's period and amplitude — from a rigid train to an irregular cloud. Deterministic (it reproduces with the seed).", "", ""};
        t["PULSAR"]["mask"] = LearnEntry{"Probability of SKIPPING a pulsaret (Roads): 0 = a full train, 1 = almost all silence. It thins the texture without changing the pitch.", "The masking of pulsar synthesis — it creates burlesque rhythmic patterns by subtraction.", ""};
        t["PULSAR"]["spread"] = LearnEntry{"Alternating pulsarets thrown to L/R (± spread) — stereo width by granulation. 0 = mono.", "", ""};
        t["PULSAR"]["level"] = LearnEntry{"Output, with a softclip (tanh) before it.", "", ""};
