        t["SPECTRA"]["voices"] = LearnEntry{"How many sinusoids the re-synthesis bank uses (2–24). Few = a caricature of the spectrum; many = a faithful re-synthesis. Each voice inherits one of the strongest partials the analysis found.", "Spectral resynthesis (Panharmonium / phase vocoder): the module LISTENS to `in`, finds the peaks of the short-term spectrum and re-oscillates. `ADDITIVE` builds from nothing; here the material is the sound coming in.", "A low VOICE + STRETCH = an inharmonic shadow of the sound. OSC/ADDITIVE → IN, a high VOICE = almost a clone."};
        t["SPECTRA"]["blur"] = LearnEntry{"How FAST each voice chases the partial it inherited: 0 = it locks onto the sound (transients get through), 1 = it drags ~0.6 s (it blurs, a ghost chorus, the sound 'melts').", "It is the time constant of the voices' freq/amp glide — no zipper at any position.", ""};
        t["SPECTRA"]["shift"] = LearnEntry{"Transposes the RE-SYNTHESIS (±2 octaves, +1 V/oct CV on PIT) without touching the analysis — a spectrum pitch-shift, formant and all.", "", "LFO → PIT: the whole spectrum rises and falls."};
