        t["SPECTRA"]["freeze"] = LearnEntry{"Freezes the voices' targets: the analysis stops, the bank goes on oscillating on the last spectrum. An infinite pad from any sound.", "It is the classic *spectral freeze*. Remove the input after freezing and the note stays.", "FRZ ← a CLOCK gate: windows of fixed spectrum alternating with the live sound."};
