        t["OSC"]["prox"] = LearnEntry{"Mélange une version étouffée de lui-même — de la « profondeur » sans avoir besoin d’un autre module.", "prox=0 c’est exactement la sortie brute ; en montant, cela mélange par-dessus un passe-bas à 1 pôle très doux.", "Montez PROX lentement sur une sortie SAW riche en harmoniques : le son s’assombrit sans FILTER."};
