        t["WAVETABLE"]["pos"] = LearnEntry{"Position sur l’axe de FORME : 0 = scie, ⅓ = carrée, ⅔ = formant (une voyelle), 1 = sinus. S’ajoute à la CV de POS et au DRIFT.", "Les 16 tables sont générées par une recette spectrale fixe dans prepare() — sans fichier de données ; à bande limitée en 10 mip-maps pour ne pas aliaser dans l’aigu.", "Branchez ENVELOPE.env → POS : la forme s’ouvre avec la note."};
        t["WAVETABLE"]["warp"] = LearnEntry{"Distorsion de phase (Casio CZ / le WAVE CUT du WAVE-6) : elle comprime la première moitié du cycle dans une fenêtre qui se resserre — de l’identité (0) à une quasi-impulsion brillante (1).", "Elle ne change pas la table, seulement la façon dont la phase la parcourt — elle crée des harmoniques aiguës gratuitement.", ""};
