        t["WAVETABLE"]["in:pitch"] = LearnEntry{"CV 1 V/oct.", "", ""};
        t["WAVETABLE"]["in:pos"] = LearnEntry{"CV ajoutée à POS (un LFO, une enveloppe, DRIFT…).", "", ""};
        t["WAVETABLE"]["in:fm"] = LearnEntry{"Audio pour la FM linéaire (× FM_AMOUNT).", "", ""};
        t["WAVETABLE"]["in:capture"] = LearnEntry{"Audio à capturer comme table — depuis un AUDIO-IN, un OSC, n’importe quelle sortie audio du graphe.", "Sans câble ici, GRAB ne fait rien et POS=1 c’est le sinus procédural.", ""};
        t["WAVETABLE"]["in:grab"] = LearnEntry{"Trigger : au front montant, il prend 1024 échantillons de CAPTURE (DC retirée + normalisée) — cela devient l’image au sommet de POS (un crossfade de ~0,9 à 1,0). Sans détection de hauteur : accordez la source à l’oreille.", "Branchez CLOCK → GRAB : la table se renouvelle à chaque mesure.", ""};
        t["WAVETABLE"]["out:out"] = LearnEntry{"La forme d’onde balayée.", "", ""};
        t["ADDITIVE"]["freq"] = LearnEntry{"Fréquence de base. 1 V/oct par l’entrée 1V/O.", "", ""};
        t["ADDITIVE"]["fine"] = LearnEntry{"Accord fin en cents (±100).", "", ""};
        t["ADDITIVE"]["tilt"] = LearnEntry{"Brillance — l’inclinaison du spectre. 0 = sombre (les harmoniques chutent vite, ~k^-2,6) ; 1 = presque plat (les 64 partiels tous forts).", "C’est l’inverse d’un filtre : au lieu de couper l’aigu, on choisit combien d’énergie chaque partiel reçoit à la construction.", "Branchez ENVELOPE.env → TILT : le timbre ouvre sa brillance avec la note."};
        t["ADDITIVE"]["comb"] = LearnEntry{"Peigne spectral : il creuse des vallées dans le spectre. 0 = plat ; 1 = 12 dents, vallées profondes — un formant grossier ou un effet de filtre en peigne, sans rien filtrer.", "g_k = (1−comb) + comb·(0,5 + 0,5·cos(2π·dents·k/64)), dents = 1 + 11·comb.", ""};
        t["ADDITIVE"]["odd"] = LearnEntry{"Balance impair/pair des partiels. 0 = la série complète ; +1 = impairs seulement (carrée, clarinette, creux et brillant) ; −1 = pairs seulement (une octave au-dessus, un son nasal).", "", ""};
        t["ADDITIVE"]["stretch"] = LearnEntry{"Inharmonicité — elle étire ou comprime les partiels. 0 = harmonique (rapport k) ; +1 = étiré (cloche, métal, aigu du piano) ; −1 = comprimé (partiels serrés, battement dense).", "rapport_k = k + stretch·0,004·k·(k−1) — l’effet est quadratique : presque rien sur les premiers partiels, fort sur ceux du haut.", "Modulez STRCH avec un LFO lent : le son se métallise puis revient."};
        t["ADDITIVE"]["drift"] = LearnEntry{"Scintillement — chaque partiel reçoit un micro-désaccord et une respiration d’amplitude venue de sinusoïdes lentes. 0 = déterministe.", "Sans RNG : c’est la somme de sinusoïdes incommensurables, donc le parcours ne se répète pas mais le rendu est reproductible.", ""};
        t["ADDITIVE"]["fm_amount"] = LearnEntry{"Profondeur de la FM linéaire de l’entrée FM.", "", ""};
        t["ADDITIVE"]["in:pitch"] = LearnEntry{"CV 1 V/oct.", "", ""};
        t["ADDITIVE"]["in:tilt"] = LearnEntry{"CV ajoutée à TILT.", "", ""};
        t["ADDITIVE"]["in:stretch"] = LearnEntry{"CV ajoutée à STRCH.", "", ""};
        t["ADDITIVE"]["in:fm"] = LearnEntry{"Audio pour la FM linéaire (× FM_AMOUNT).", "", ""};
        t["ADDITIVE"]["out:out"] = LearnEntry{"La somme des 64 partiels, avec un suiveur de gain + tanh pour éviter la saturation.", "", ""};
        t["OPERATOR"]["freq"] = LearnEntry{"Fréquence de l’opérateur A. 1 V/oct par l’entrée 1V/O.", "", ""};
        t["OPERATOR"]["fine"] = LearnEntry{"Accord fin en cents (±100).", "", ""};
        t["OPERATOR"]["algo"] = LearnEntry{"Quel opérateur module lequel — 8 algorithmes, de 0 (A→B→C→D, le plus « FM ») à 7 (A,B,C,D en parallèle, additif/orgue).", "L’ordre est toujours A→B→C→D et seul A a de la rétroaction, donc il n’y a pas de boucle entre opérateurs — le calcul se fait en une passe.", "Commencez à 0 avec un INDEX moyen et tournez ALGO lentement : le spectre se réorganise à chaque pas."};
        t["OPERATOR"]["index"] = LearnEntry{"Profondeur de modulation globale. 0 = les 4 opérateurs sont des sinusoïdes pures ; 1 ≈ 6 cycles d’écart de phase (très brillant).", "En FM, l’indice contrôle combien de bandes latérales apparaissent et avec quelle force (les fonctions de Bessel de Chowning).", "Branchez ENVELOPE.env → IDX : l’attaque brillante qui s’assombrit dans la queue — le « son DX »."};
        t["OPERATOR"]["feedback"] = LearnEntry{"L’opérateur A module sa propre phase (la moyenne des 2 derniers échantillons, à la DX7).", "À lui seul il mène déjà la sinusoïde d’A vers une dent de scie — une source d’harmoniques sans avoir besoin d’un autre opérateur.", ""};
        t["OPERATOR"]["ratio_b"] = LearnEntry{"Rapport de fréquence de l’opérateur B par rapport à A, QUANTIFIÉ : 0,5 / 1 / 1,5 / 2 / 2,5 / 3 / 4 / 5 / 7 / 9.", "Un nombre entier = harmonique (timbre musical) ; une fraction (2,5) = inharmonique (cloche, métal). C’est le QUANTIZER de la hauteur, mais pour le timbre.", ""};
        t["OPERATOR"]["ratio_c"] = LearnEntry{"Rapport de l’opérateur C (la même table).", "", ""};
        t["OPERATOR"]["ratio_d"] = LearnEntry{"Rapport de l’opérateur D (la même table).", "", ""};
        t["OPERATOR"]["drift"] = LearnEntry{"Micro-désaccord lent et indépendant par opérateur. Déterministe (somme de sinus, sans RNG). 0 = aucun désaccord.", "", ""};
        t["OPERATOR"]["in:pitch"] = LearnEntry{"CV 1 V/oct.", "", ""};
