        t["OPERATOR"]["out:out"] = LearnEntry{"La somme des porteuses de l’algorithme, ÷ le nombre de porteuses + softclip.", "", ""};
        t["PULSAR"]["freq"] = LearnEntry{"Taux de répétition des pulsarets = la HAUTEUR (20–2000 Hz, +CV 1 V/oct). Chaque déclenchement lance un grain ; le silence entre eux est ce qui définit la note.", "Synthèse pulsar (Curtis Roads) : un train de pulsarets — grain court + silence, période totale p. freq = 1/p.", "SEQUENCE.pitch → PIT : une mélodie. Descendez vers ~30 Hz et chaque pulsaret devient un événement séparé (rythme)."};
        t["PULSAR"]["formant"] = LearnEntry{"Fréquence interne du pulsaret = le TIMBRE, INDÉPENDANT de la hauteur (0,1–8×, +CV). Basse = creux/formantique ; haute = brillant/nasal. Elle ne désaccorde PAS.", "C’est la seconde fréquence de la synthèse pulsar : formant = 1/d (d = durée du pulsaret). Le peigne harmonique reste sur les multiples de freq ; le formant ne déplace que l’ENVELOPPE spectrale.", "LFO → FQM : un « wah » sans filtre. À formant≈1 le pulsaret remplit toute la période (duty 100 %)."};
        t["PULSAR"]["shape"] = LearnEntry{"Forme du pulsaret : 0 = 1 cycle de sinus ; jusqu’à 1 = 2–3 cycles + une harmonique aiguë (impulsion plus étroite et plus riche).", "", ""};
        t["PULSAR"]["window"] = LearnEntry{"Enveloppe du grain : 0 ≈ rectangulaire (transitoires dures, brillant), 0,4 = Hann (propre), 1 = expodec (attaque rapide + queue — percussif).", "La fenêtre de grain granulaire. La rectangulaire fuit en large bande aux bords ; Hann/expodec adoucissent.", ""};
        t["PULSAR"]["jitter"] = LearnEntry{"Écart Rasgo SEMÉ dans la période et l’amplitude de chaque pulsaret — du train rigide au nuage irrégulier. Déterministe (il se reproduit avec la graine).", "", ""};
        t["PULSAR"]["mask"] = LearnEntry{"Probabilité de SAUTER un pulsaret (Roads) : 0 = train plein, 1 = presque tout en silence. Cela raréfie la texture sans changer la hauteur.", "Le masking de la synthèse pulsar — il crée des motifs rythmiques burlesques par soustraction.", ""};
        t["PULSAR"]["spread"] = LearnEntry{"Pulsarets alternés envoyés à G/D (± spread) — largeur stéréo par granulation. 0 = mono.", "", ""};
        t["PULSAR"]["level"] = LearnEntry{"Sortie, avec un softclip (tanh) avant.", "", ""};
        t["PULSAR"]["in:pitch"] = LearnEntry{"CV 1 V/oct ajoutée à FREQ.", "", ""};
        t["PULSAR"]["in:formant_mod"] = LearnEntry{"CV (en octaves) ajoutée à FORMANT — elle déplace le timbre sans toucher à la hauteur.", "", ""};
        t["PULSAR"]["out:out"] = LearnEntry{"Canal gauche (mono si SPREAD=0).", "", ""};
