        t["SPECTRA"]["voices"] = LearnEntry{"Combien de sinusoïdes le banc de resynthèse utilise (2–24). Peu = une caricature du spectre ; beaucoup = une resynthèse fidèle. Chaque voix hérite d’un des partiels les plus forts trouvés par l’analyse.", "Resynthèse spectrale (Panharmonium / vocodeur de phase) : le module ÉCOUTE `in`, trouve les pics du spectre à court terme et ré-oscille. L’`ADDITIVE` construit à partir de rien ; ici le matériau est le son qui entre.", "Un VOICE faible + STRETCH = une ombre inharmonique du son. OSC/ADDITIVE → IN, un VOICE élevé = presque un clone."};
        t["SPECTRA"]["blur"] = LearnEntry{"À quelle VITESSE chaque voix poursuit le partiel qu’elle a hérité : 0 = elle se verrouille sur le son (les transitoires passent), 1 = elle traîne ~0,6 s (cela floute, chœur fantôme, le son « fond »).", "C’est la constante de temps du glissement fréq/amp des voix — sans zipper à aucune position.", ""};
        t["SPECTRA"]["shift"] = LearnEntry{"Transpose la RESYNTHÈSE (±2 octaves, +CV 1 V/oct sur PIT) sans toucher à l’analyse — un pitch-shift du spectre, formant compris.", "", "LFO → PIT : le spectre entier monte et descend."};
        t["SPECTRA"]["stretch"] = LearnEntry{"Écarte/rapproche les partiels de la resynthèse autour du milieu → inharmonique (cloche, métal) sans changer la hauteur perçue.", "", ""};
        t["SPECTRA"]["tone"] = LearnEntry{"Inclinaison spectrale de la sortie : <0 elle atténue l’aigu des voix, >0 elle le relève. 0 = fidèle à l’analyse.", "", ""};
        t["SPECTRA"]["jitter"] = LearnEntry{"Wobble lent et SEMÉ dans la fréquence de chaque voix (±3 %·jitter) — la resynthèse « respire », jamais identique. Déterministe. 0 = statique.", "", ""};
        t["SPECTRA"]["freeze"] = LearnEntry{"Gèle les cibles des voix : l’analyse s’arrête, le banc continue d’osciller sur le dernier spectre. Un pad infini à partir de n’importe quel son.", "C’est le *spectral freeze* classique. Retirez l’entrée après le gel et la note reste.", "FRZ ← un gate du CLOCK : des fenêtres de spectre fixe alternant avec le son vivant."};
        t["SPECTRA"]["mix"] = LearnEntry{"Sec (ce qui entre dans IN) ↔ resynthétisé. 0 = bypass. Sans IN, seul le mouillé compte.", "", ""};
        t["SPECTRA"]["in:in"] = LearnEntry{"Le son à ANALYSER — n’importe quelle voix, un DRUM, un enregistrement. Laissée libre → un bruit interne de −30 dB avec deux partiels qui dérivent lentement (semés) alimente l’analyse : SPECTRA seul est un drone tonal qui évolue.", "", ""};
        t["SPECTRA"]["in:pitch"] = LearnEntry{"CV 1 V/oct ajoutée à SHIFT.", "", ""};
