        t["PLL"]["freq"] = LearnEntry{"Fréquence libre — utilisée quand REF n’est pas branchée, et comme point de départ quand elle l’est.", "", ""};
        t["PLL"]["fine"] = LearnEntry{"Accord fin en cents.", "", ""};
        t["PLL"]["shape"] = LearnEntry{"Morphing continu : sinus → triangle → scie → carrée.", "", ""};
        t["PLL"]["ratio"] = LearnEntry{"Multiplie la phase de la référence avant de comparer — le PLL se verrouille sur des sous/sur-harmoniques de REF, pas seulement sur la même note.", "Un RATIO faible se verrouille sur un sous-multiple très lent de la référence — presque un diviseur d’horloge par boucle de phase.", "Branchez REF sur un OSC.saw grave et balayez RATIO : le PLL saute entre le verrouillage à l’octave, à la quinte, à des diviseurs très profonds."};
        t["PLL"]["lock_gain"] = LearnEntry{"Avec quelle force le PLL poursuit la référence — faible il « chasse » lentement, élevé il se verrouille vite (mais plus instable si le rapport ne colle pas exactement).", "", ""};
        t["PLL"]["fm_amount"] = LearnEntry{"Quantité de FM linéaire par l’entrée FM.", "", ""};
        t["PLL"]["feedback_amount"] = LearnEntry{"Quelle part du réseau de rétroaction (FTYP) entre dans la phase lue.", "Le réseau module la PHASE, pas la fréquence, et seulement sur la LECTURE de la forme — il n’écrit jamais dans l’accumulateur de phase (c’est pourquoi il ne désaccorde pas le PLL, il ne crée que de la texture).", ""};
        t["PLL"]["feedback_type"] = LearnEntry{"Type de rétroaction : direct / redressé / capacitif (mémoire lente) / impulsion / « transistor » (tanh asymétrique) / reflux.", "", ""};
        t["PLL"]["in:pitch"] = LearnEntry{"CV 1 V/oct — multiplie FREQ.", "", ""};
        t["PLL"]["in:fm"] = LearnEntry{"Entrée de FM linéaire.", "", ""};
        t["PLL"]["in:ref"] = LearnEntry{"Référence externe (une scie bipolaire, par ex. OSC.saw) — présente, le PLL poursuit sa phase au lieu de tourner librement.", "", ""};
        t["PLL"]["out:out"] = LearnEntry{"La forme d’onde (SHAPE), à la fréquence corrigée par la poursuite de phase.", "", ""};
        t["PLL"]["out:ring"] = LearnEntry{"out × ref — le même hétérodyne classique entre deux oscillateurs.", "", ""};
        t["PLL"]["out:lock"] = LearnEntry{"0..1 — à quel point le détecteur de phase est proche de zéro (1 = verrouillé).", "", "Branchez LOCK sur un VCA : le volume monte tout seul quand le PLL se verrouille sur la référence, et tombe quand il « chasse »."};
        t["CHORD"]["freq"] = LearnEntry{"Fréquence de base — la fondamentale de l’accord.", "", ""};
        t["CHORD"]["chord"] = LearnEntry{"Choisit la forme de l’accord parmi 10 tables (unisson, octaves, quinte, majeur, mineur, sus4, maj7, min7, dim, add9).", "", ""};
        t["CHORD"]["voices"] = LearnEntry{"Combien de voix sonnent (2-4) — moins de voix, un accord plus simple même avec CHORD élevé.", "", ""};
        t["CHORD"]["inversion"] = LearnEntry{"Monte les voix les plus graves d’une octave — une inversion de l’accord.", "", ""};
        t["CHORD"]["detune"] = LearnEntry{"Désaccorde légèrement les voix entre elles — un chœur.", "", ""};
        t["CHORD"]["wave"] = LearnEntry{"Fait un morphing de la forme de chaque voix : scie → impulsion → triangle.", "", ""};
        t["CHORD"]["drift"] = LearnEntry{"Marche lente et indépendante par voix.", "", ""};
        t["CHORD"]["voicing"] = LearnEntry{"Active la conduite des voix : au changement d’accord, chaque voix glisse vers le ton le PLUS PROCHE de celui qu’elle jouait, au lieu de sauter directement.", "Sans VLEAD tout changement est parallèle (toutes les voix sautent ensemble) ; avec VLEAD le mouvement est minimal — une affectation gloutonne par distance, avec glide.", "Comparez CHORD en variation avec VLEAD activé/désactivé : désactivé cela sonne « en bloc », activé cela sonne comme un chœur qui conduit ses voix."};
        t["CHORD"]["in:pitch"] = LearnEntry{"CV 1 V/oct — s’ajoute à la base FREQ.", "", ""};
        t["CHORD"]["in:chord_cv"] = LearnEntry{"CV qui s’ajoute au potentiomètre CHORD — modulez-la avec HARMONY.root pour des progressions qui changent toutes seules.", "", ""};
