        t["CHORD"]["out:out"] = LearnEntry{"Somme normalisée (1/√voix) des voix actives.", "", ""};
        t["NOISE"]["rate"] = LearnEntry{"Rythme de l’horloge interne du S&H/smooth (ignoré si TRIG est branchée).", "", ""};
        t["NOISE"]["slew"] = LearnEntry{"Temps de glissement de la sortie SMTH — 0 c’est instantané (un palier, cela devient presque un S&H), 1 c’est ~2 s de glisse.", "", ""};
        t["NOISE"]["spread"] = LearnEntry{"Tire le tirage de l’uniforme vers la cloche (la moyenne de 4 uniformes) — cela affecte SH et SMTH.", "spread=0 est uniforme (il tombe pareil sur n’importe quelle valeur) ; spread=1 concentre près de 0.", ""};
        t["NOISE"]["poisson"] = LearnEntry{"Remplace l’horloge interne périodique par un processus de Poisson LIBRE — SH/SMTH se mettent à jour à des instants aléatoires, non asservis à une horloge. RATE devient le taux moyen.", "L’intervalle est un mélange entre la période régulière et un tirage exponentiel (t = −ln(U)/λ) ; poisson=1 c’est du Poisson pur. Ignoré si TRIG est branchée.", "C’est le « compteur Geiger » — le pendant de la sortie GEIG du BOXCAR (#51). Semé : deux rendus identiques."};
        t["NOISE"]["in:trigger"] = LearnEntry{"Trigger externe pour le S&H/SMTH — présent, il remplace l’horloge interne (RATE).", "", ""};
        t["NOISE"]["in:in"] = LearnEntry{"Source que le S&H échantillonne — sans câble, le S&H utilise le tirage interne au lieu de l’entrée.", "", ""};
        t["NOISE"]["out:white"] = LearnEntry{"Bruit blanc — énergie égale à toute fréquence.", "", ""};
        t["NOISE"]["out:pink"] = LearnEntry{"Bruit rose — chute de ~3 dB/octave (filtre Kellet à 7 pôles). Plus naturel pour le vent/la mer que le blanc.", "", ""};
        t["NOISE"]["out:brown"] = LearnEntry{"Bruit brun — chute de ~6 dB/octave (marche aléatoire filtrée). Grave, sourd.", "", ""};
        t["NOISE"]["out:sh"] = LearnEntry{"Sample & hold — il maintient une nouvelle valeur à chaque impulsion (RATE ou TRIG), par paliers.", "", ""};
        t["NOISE"]["out:smooth"] = LearnEntry{"Une tension qui glisse vers une nouvelle cible à chaque impulsion, au lieu de sauter — le « smooth random » du Buchla 266.", "", "Comparez SH et SMTH au même RATE : SH saute, SMTH glisse."};
