        t["NOISE"]["out:violet"] = LearnEntry{"Bruit violet — monte de ~6 dB/octave (différencié 2×). Encore plus aigu que le bleu — presque uniquement du souffle.", "", ""};
        t["NOISE"]["out:bit"] = LearnEntry{"1 bit bipolaire (+1/−1) directement du générateur, qui change à chaque échantillon — une texture numérique dure, différente du palier du S&H (qui ne change qu’à l’impulsion).", "", ""};
        t["MATTER"]["freq"] = LearnEntry{"Fréquence fondamentale du banc de modes.", "", ""};
        t["MATTER"]["structure"] = LearnEntry{"Corde (0, modes harmoniques) → cloche/métal (1, modes étirés/inharmoniques).", "", ""};
        t["MATTER"]["brightness"] = LearnEntry{"Combien de modes aigus sonnent — la décroissance d’amplitude par mode.", "", ""};
        t["MATTER"]["damping"] = LearnEntry{"Combien de temps les modes continuent de sonner après avoir été excités.", "", ""};
        t["MATTER"]["position"] = LearnEntry{"Où l’objet est excité — cela décide QUELS modes reçoivent de l’énergie (frapper sur le nœud d’une harmonique ne l’excite pas).", "", "Balayez POS lentement avec une frappe constante : certains modes disparaissent, d’autres apparaissent — c’est la physique réelle du jeu en un point différent."};
        t["MATTER"]["exciter"] = LearnEntry{"Quelle quantité de bruit entre dans la rafale de la frappe interne.", "", ""};
        t["MATTER"]["mix"] = LearnEntry{"Sec (excitation brute) ↔ mouillé (résonance des modes).", "", ""};
        t["MATTER"]["in:in"] = LearnEntry{"Entrée audio pour exciter les modes (un clic, du bruit, une voix).", "", ""};
        t["MATTER"]["in:strike"] = LearnEntry{"Trigger — déclenche une frappe interne (une courte rafale de bruit).", "", ""};
        t["MATTER"]["in:freq_mod"] = LearnEntry{"CV 1 V/oct qui multiplie FREQ.", "", ""};
        t["MATTER"]["in:struct_mod"] = LearnEntry{"CV qui s’ajoute à STRC.", "", ""};
        t["MATTER"]["out:out"] = LearnEntry{"Mélange entre l’excitation brute et la résonance des 24 modes.", "", ""};
        t["STRING"]["freq"] = LearnEntry{"Fréquence de la corde — la longueur de la boucle de retard.", "", ""};
        t["STRING"]["decay"] = LearnEntry{"Sustain — combien de temps la corde continue de sonner.", "", ""};
        t["STRING"]["damping"] = LearnEntry{"Brillance — élevé, cela laisse la corde plus sombre, en éteignant les harmoniques plus vite.", "", ""};
        t["STRING"]["position"] = LearnEntry{"Où la corde est pincée — un filtre en peigne sur l’excitation, dont le nœud en POS n’est pas excité.", "", "Balayez POS : en certains points, des harmoniques disparaissent — c’est la physique réelle du pincement d’une corde en des endroits différents."};
        t["STRING"]["exciter"] = LearnEntry{"Quelle quantité de bruit entre dans la frappe (PLK).", "", ""};
        t["STRING"]["drive"] = LearnEntry{"Sature la boucle de la corde — plus de grain, moins propre.", "", ""};
        t["STRING"]["mix"] = LearnEntry{"Sec ↔ résonance de la corde.", "", ""};
        t["STRING"]["in:in"] = LearnEntry{"Entrée continue — elle excite la corde comme un archet, au lieu d’une frappe unique.", "Le tanh dans la boucle garantit la stabilité — l’archet mène à un cycle limite, non à la divergence (le même principe que le FILTER en auto-oscillation).", ""};
        t["STRING"]["in:pluck"] = LearnEntry{"Trigger — pince la corde (une rafale de bruit filtrée par la position).", "", ""};
