        t["DRUM"]["tone"] = LearnEntry{"Hauteur du corps (20–1000 Hz). Grave = grosse caisse, médium = tom/caisse claire, aigu = clave. 1 V/oct par l’entrée PIT.", "Le corps est une sinusoïde avec une enveloppe de hauteur — à la frappe la fréquence bondit puis retombe sur TONE (le « pow » de la 808).", ""};
        t["DRUM"]["bend"] = LearnEntry{"Profondeur de l’enveloppe de hauteur. 0 = tonal (la fréquence reste sur TONE) ; 1 = un balayage de grosse caisse (elle bondit ×6 puis descend).", "C’est le pitch-sweep classique de la voix de grosse caisse — ce qui donne du poids au transitoire.", ""};
        t["DRUM"]["decay"] = LearnEntry{"Temps de décroissance général (~20 ms à ~2 s). Court = un clic/laser ; long = un sub qui se soutient.", "", ""};
        t["DRUM"]["snap"] = LearnEntry{"Dose de la rafale de bruit d’attaque — le « crack » de la caisse claire, le souffle du charleston, le clic de la grosse caisse.", "Du bruit blanc à travers un passe-haut dont la coupure monte avec MAP (808 sourde → acoustique brillante), avec une enveloppe propre très courte.", ""};
        t["DRUM"]["map"] = LearnEntry{"Caractère 808 → 909 → acoustique. En montant : le corps gagne un clic (tanh), le bruit devient plus aigu, un peu de drive entre.", "", ""};
        t["DRUM"]["drive"] = LearnEntry{"Saturation de sortie (tanh + makeup) — le crunch de la 909.", "", ""};
        t["DRUM"]["roll"] = LearnEntry{"Auto-déclenchement interne. 0 = seulement le gate externe ; au-delà, la voix se redéclenche à ~2–40 Hz — roulement, buzz, et le mode qui joue tout seul.", "", ""};
        t["DRUM"]["drift"] = LearnEntry{"Humanisation : chaque frappe varie légèrement en hauteur/décroissance/niveau. D’un xorshift semé et avancé SUR le déclenchement — les mêmes gates → le même audio. 0 = frappes identiques.", "", ""};
        t["DRUM"]["in:gate"] = LearnEntry{"Trigger — une impulsion, une frappe.", "", ""};
        t["DRUM"]["in:accent"] = LearnEntry{"CV d’accent : elle met à l’échelle le niveau (et la brillance) de la frappe. Branchez TRIGSEQ.accent ici.", "", ""};
        t["DRUM"]["in:tone"] = LearnEntry{"CV 1 V/oct ajoutée par-dessus le potentiomètre TONE (des toms accordés depuis un SEQUENCE).", "", ""};
        t["DRUM"]["out:out"] = LearnEntry{"La voix — corps + crack, saturée par DRIVE.", "", ""};
        t["SIGNAL-IN"]["gain"] = LearnEntry{"Gain appliqué à l’entrée audio en direct.", "", ""};
        t["SIGNAL-IN"]["bend"] = LearnEntry{"Plage du pitch-bend MIDI, en demi-tons (0–24). Elle affecte la sortie 1V/O.", "", ""};
        t["SIGNAL-IN"]["cc_num"] = LearnEntry{"Quel Control Change MIDI la sortie CC suit (1 = molette de modulation).", "", ""};
        t["SIGNAL-IN"]["listen"] = LearnEntry{"Active l’entrée extérieure : l’audio du système (micro, instrument) et le MIDI. Elle démarre éteinte — l’application n’ouvre le micro et le MIDI que si elle est allumée et qu’une sortie est câblée.", "", ""};
        t["SIGNAL-IN"]["out:out"] = LearnEntry{"Audio de l’entrée du système, canal gauche — sans rien qui capture, du silence (il ne se bloque jamais, il ne lit jamais de déchets).", "Le côté récepteur d’un anneau SPSC alimenté par un thread de capture externe (`AlsaSource`) ; le cœur `rasgo_modular_core` ne sait pas ce qu’est ALSA.", "Lancez un autre instrument et branchez L sur un FILTER — le Rasgo se met à traiter de l’audio venu de l’extérieur."};
        t["SIGNAL-IN"]["out:r"] = LearnEntry{"Audio de l’entrée, canal droit.", "", ""};
        t["SIGNAL-IN"]["out:pitch"] = LearnEntry{"Hauteur de la note MIDI jouée, en CV 1 V/oct (note 60 = 0 V), avec le pitch-bend ajouté (× BEND).", "Une voix MONOPHONIQUE avec pile de notes (last-note priority) : relâchez la note du haut et celle du bas resonne à nouveau. C’est le pendant en entrée du NOTE-OUT.", ""};
        t["SIGNAL-IN"]["out:gate"] = LearnEntry{"Haut tant qu’une touche est enfoncée (une rampe anti-clic de 1 ms).", "", ""};
        t["SIGNAL-IN"]["out:vel"] = LearnEntry{"Vélocité de la dernière note (0–1), maintenue.", "", ""};
