        t["OSC"]["pw"] = LearnEntry{"Anchura de pulso — sólo afecta a la salida PLS.", "En 0,5 el pulso es onda cuadrada; en los extremos se vuelve un tren de picos finos.", "Module PWM con un LFO lento y oiga el pulso \"respirar\"."};
        t["OSC"]["fm_amount"] = LearnEntry{"Cantidad de FM lineal through-zero por la entrada FM.", "dp puede volverse negativo — la fase anda hacia atrás, FM de verdad (no la FM de fase, que \"se rompe\" en tasa de audio).", "Suba FM con otro OSC en la entrada FM: en tasa de audio se vuelve timbre metálico."};
