        t["OSC"]["prox"] = LearnEntry{"Mezcla una versión apagada de sí mismo — \"profundidad\" sin necesitar otro módulo.", "prox=0 es exactamente la salida cruda; al subir, mezcla encima un paso bajo de 1 polo muy suave.", "Suba PROX despacio en una salida SAW rica en armónicos: el sonido se oscurece sin necesitar un FILTER."};
