        t["WAVETABLE"]["freq"] = LearnEntry{"Frecuencia base. 1 V/oct por la entrada 1V/O.", "", ""};
        t["WAVETABLE"]["fine"] = LearnEntry{"Afinación fina en cents (±100).", "", ""};
        t["WAVETABLE"]["pos"] = LearnEntry{"Posición en el eje de FORMA: 0 = sierra, ⅓ = cuadrada, ⅔ = formante (una vocal), 1 = seno. Se suma a la CV de POS y al DRIFT.", "Las 16 tablas se generan por una receta espectral fija en prepare() — sin archivo de datos; de banda limitada en 10 mip-maps para no aliasar en afinación alta.", "Cablee ENVELOPE.env → POS: la forma se abre junto con la nota."};
        t["WAVETABLE"]["warp"] = LearnEntry{"Distorsión de fase (Casio CZ / el WAVE CUT del WAVE-6): comprime la primera mitad del ciclo en una ventana que se encoge — de la identidad (0) a un casi pulso brillante (1).", "No cambia la tabla, sólo cómo la fase la recorre — crea armónicos agudos de regalo.", ""};
        t["WAVETABLE"]["fm_amount"] = LearnEntry{"Profundidad de la FM lineal de la entrada FM.", "", ""};
