        t["ADDITIVE"]["tilt"] = LearnEntry{"Brillo — la inclinación del espectro. 0 = oscuro (los armónicos caen rápido, ~k^-2,6); 1 = casi plano (los 64 parciales fuertes).", "Es lo contrario de un filtro: en vez de cortar el agudo, se elige cuánta energía recibe cada parcial al construirse.", "Cablee ENVELOPE.env → TILT: el timbre abre el brillo junto con la nota."};
        t["ADDITIVE"]["comb"] = LearnEntry{"Peine espectral: cava valles en el espectro. 0 = plano; 1 = 12 dientes, valles profundos — un formante grosero o un efecto de filtro de peine, sin filtrar nada.", "g_k = (1−comb) + comb·(0,5 + 0,5·cos(2π·dientes·k/64)), dientes = 1 + 11·comb.", ""};
        t["ADDITIVE"]["odd"] = LearnEntry{"Balance impar/par de los parciales. 0 = la serie completa; +1 = sólo impares (cuadrada, clarinete, hueco y brillante); −1 = sólo pares (una octava arriba, sonido nasal).", "", ""};
        t["ADDITIVE"]["stretch"] = LearnEntry{"Inarmonicidad — estira o comprime los parciales. 0 = armónico (razón k); +1 = estirado (campana, metal, agudo del piano); −1 = comprimido (parciales juntos, batido denso).", "razón_k = k + stretch·0,004·k·(k−1) — el efecto es cuadrático: casi nada en los primeros parciales, fuerte en los de arriba.", "Module STRCH con un LFO lento: el sonido se metaliza y vuelve."};
        t["ADDITIVE"]["drift"] = LearnEntry{"Centelleo — cada parcial recibe un microdesafine y una respiración de amplitud de senoides lentas. 0 = determinista.", "Sin RNG: es la suma de senoides inconmensurables, así que el recorrido no se repite pero el render es reproducible.", ""};
        t["ADDITIVE"]["fm_amount"] = LearnEntry{"Profundidad de la FM lineal de la entrada FM.", "", ""};
        t["ADDITIVE"]["in:pitch"] = LearnEntry{"CV 1 V/oct.", "", ""};
        t["ADDITIVE"]["in:tilt"] = LearnEntry{"CV sumada a TILT.", "", ""};
        t["ADDITIVE"]["in:stretch"] = LearnEntry{"CV sumada a STRCH.", "", ""};
        t["ADDITIVE"]["in:fm"] = LearnEntry{"Audio para FM lineal (× FM_AMOUNT).", "", ""};
        t["ADDITIVE"]["out:out"] = LearnEntry{"La suma de los 64 parciales, con seguidor de ganancia + tanh para no reventar.", "", ""};
        t["OPERATOR"]["freq"] = LearnEntry{"Frecuencia del operador A. 1 V/oct por la entrada 1V/O.", "", ""};
        t["OPERATOR"]["fine"] = LearnEntry{"Afinación fina en cents (±100).", "", ""};
        t["OPERATOR"]["algo"] = LearnEntry{"Qué operador modula a cuál — 8 algoritmos, de 0 (A→B→C→D, el más 'FM') a 7 (A,B,C,D en paralelo, aditivo/órgano).", "El orden siempre es A→B→C→D y sólo A tiene realimentación, así que no hay lazo entre operadores — el cálculo es una pasada.", "Empiece en 0 con un INDEX medio y gire ALGO despacio: el espectro se reorganiza en cada paso."};
        t["OPERATOR"]["index"] = LearnEntry{"Profundidad de modulación global. 0 = los 4 operadores son senoides puras; 1 ≈ 6 ciclos de desvío de fase (muy brillante).", "En FM, el índice controla cuántas bandas laterales aparecen y con qué fuerza (las funciones de Bessel de Chowning).", "Cablee ENVELOPE.env → IDX: el ataque brillante que se oscurece en la cola — el 'sonido DX'."};
        t["OPERATOR"]["feedback"] = LearnEntry{"El operador A modula su propia fase (el promedio de las 2 últimas muestras, al estilo DX7).", "Por sí solo ya lleva la senoide de A a un diente de sierra — una fuente de armónicos sin necesitar otro operador.", ""};
        t["OPERATOR"]["ratio_b"] = LearnEntry{"Razón de frecuencia del operador B respecto a A, CUANTIZADA: 0,5 / 1 / 1,5 / 2 / 2,5 / 3 / 4 / 5 / 7 / 9.", "Un entero = armónico (timbre musical); una fracción (2,5) = inarmónico (campana, metal). Es el QUANTIZER de la altura, pero para el timbre.", ""};
        t["OPERATOR"]["ratio_c"] = LearnEntry{"Razón del operador C (la misma tabla).", "", ""};
        t["OPERATOR"]["ratio_d"] = LearnEntry{"Razón del operador D (la misma tabla).", "", ""};
        t["OPERATOR"]["drift"] = LearnEntry{"Microdesafine lento e independiente por operador. Determinista (suma de senos, sin RNG). 0 = sin desafine.", "", ""};
        t["OPERATOR"]["in:pitch"] = LearnEntry{"CV 1 V/oct.", "", ""};
