        t["PULSAR"]["freq"] = LearnEntry{"Tasa de repetición de los pulsarets = la ALTURA (20–2000 Hz, +CV 1 V/oct). Cada disparo lanza un grano; el silencio entre ellos es lo que define la nota.", "Síntesis pulsar (Curtis Roads): un tren de pulsarets — grano corto + silencio, período total p. freq = 1/p.", "SEQUENCE.pitch → PIT: una melodía. Baje hasta ~30 Hz y cada pulsaret se vuelve un evento separado (ritmo)."};
        t["PULSAR"]["formant"] = LearnEntry{"Frecuencia interna del pulsaret = el TIMBRE, INDEPENDIENTE de la altura (0,1–8×, +CV). Baja = hueco/formántico; alta = brillante/nasal. NO desafina.", "Es la segunda frecuencia de la síntesis pulsar: formant = 1/d (d = duración del pulsaret). El peine armónico queda en múltiplos de freq; formant sólo mueve la ENVOLVENTE espectral.", "LFO → FQM: un 'wah' sin filtro. En formante≈1 el pulsaret llena todo el período (duty 100 %)."};
        t["PULSAR"]["shape"] = LearnEntry{"Forma del pulsaret: 0 = 1 ciclo de seno; hasta 1 = 2–3 ciclos + un armónico agudo (pulso más estrecho y rico).", "", ""};
        t["PULSAR"]["window"] = LearnEntry{"Envolvente del grano: 0 ≈ rectangular (transitorios duros, brillante), 0,4 = Hann (limpio), 1 = expodec (ataque rápido + cola — percusivo).", "La ventana del grano granular. La rectangular fuga banda ancha en los bordes; Hann/expodec suavizan.", ""};
        t["PULSAR"]["jitter"] = LearnEntry{"Desvío Rasgo SEMBRADO en el período y la amplitud de cada pulsaret — de tren rígido a nube irregular. Determinista (se reproduce con la semilla).", "", ""};
        t["PULSAR"]["mask"] = LearnEntry{"Probabilidad de SALTARSE un pulsaret (Roads): 0 = tren lleno, 1 = casi todo silencio. Ralea la textura sin cambiar la altura.", "El masking de la síntesis pulsar — crea patrones rítmicos burlescos por sustracción.", ""};
        t["PULSAR"]["spread"] = LearnEntry{"Pulsarets alternados lanzados a L/R (± spread) — anchura estéreo por granulación. 0 = mono.", "", ""};
