        t["SPECTRA"]["voices"] = LearnEntry{"Cuántas senoides usa el banco de resíntesis (2–24). Pocas = caricatura del espectro; muchas = resíntesis fiel. Cada voz hereda uno de los parciales más fuertes que halló el análisis.", "Resíntesis espectral (Panharmonium / phase vocoder): el módulo ESCUCHA `in`, halla los picos del espectro de corto plazo y reoscila. El `ADDITIVE` construye de cero; aquí el material es el sonido que entra.", "Un VOICE bajo + STRETCH = una sombra inarmónica del sonido. OSC/ADDITIVE → IN, un VOICE alto = casi un clon."};
        t["SPECTRA"]["blur"] = LearnEntry{"Con qué RAPIDEZ persigue cada voz el parcial que heredó: 0 = se traba en el sonido (los transitorios pasan), 1 = arrastra ~0,6 s (difumina, coro fantasma, el sonido se 'derrite').", "Es la constante de tiempo del deslizamiento freq/amp de las voces — sin zíper en ninguna posición.", ""};
        t["SPECTRA"]["shift"] = LearnEntry{"Transpone la RESÍNTESIS (±2 octavas, +CV 1 V/oct en PIT) sin tocar el análisis — pitch-shift de espectro, formante incluido.", "", "LFO → PIT: el espectro entero sube y baja."};
        t["SPECTRA"]["stretch"] = LearnEntry{"Separa/junta los parciales de la resíntesis alrededor del medio → inarmónico (campana, metal) sin cambiar la altura percibida.", "", ""};
        t["SPECTRA"]["tone"] = LearnEntry{"Inclinación espectral de la salida: <0 apaga el agudo de las voces, >0 lo realza. 0 = fiel al análisis.", "", ""};
        t["SPECTRA"]["jitter"] = LearnEntry{"Bamboleo lento y SEMBRADO en la frecuencia de cada voz (±3 %·jitter) — la resíntesis 'respira', nunca idéntica. Determinista. 0 = estático.", "", ""};
        t["SPECTRA"]["freeze"] = LearnEntry{"Congela los objetivos de las voces: el análisis para, el banco sigue oscilando en el último espectro. Un pad infinito a partir de cualquier sonido.", "Es el *spectral freeze* clásico. Quite la entrada después de congelar y la nota se queda.", "FRZ ← un gate del CLOCK: ventanas de espectro fijo alternando con el sonido vivo."};
        t["SPECTRA"]["mix"] = LearnEntry{"Seco (lo que entra en IN) ↔ resintetizado. 0 = bypass. Sin IN, sólo importa el mojado.", "", ""};
