        t["NOISE"]["poisson"] = LearnEntry{"Cambia el reloj interno periódico por un proceso de Poisson LIBRE — SH/SMTH se actualizan en tiempos aleatorios, no atados a un reloj. RATE pasa a ser la tasa media.", "El intervalo es una mezcla entre el período regular y un sorteo exponencial (t = −ln(U)/λ); poisson=1 es Poisson puro. Ignorado si TRIG está conectada.", "Es el \"contador Geiger\" — la pareja de la salida GEIG del BOXCAR (#51). Sembrado: dos renders idénticos."};
