        t["HALL"]["size"] = LearnEntry{"Size of the space — it scales the 8 line lengths from ~8 ms (a room) to ~88 ms (a hall).", "It is a feedback delay network (FDN): 8 lines + a Householder matrix (lossless) recombines them at every round. SPACE is comb+allpass; this is the network.", "Patch a slow LFO into SIZE: the room 'breathes' and detunes the tail (a tape effect)."};
        t["HALL"]["decay"] = LearnEntry{"Tail time (RT60): 0.2 s to 15 s. Close to maximum the tail hardly decays at all.", "The gain of each line comes from RT60: g = 10^(−3·time/RT60). Householder is orthogonal, so g < 1 always decays, it never blows up.", ""};
        t["HALL"]["damp"] = LearnEntry{"A low-pass inside each line's loop — the treble decays before the bass, as in a real room. 0 = bright, 1 = dark.", "", ""};
        t["HALL"]["mod"] = LearnEntry{"Depth of the modulation of each line's read point (slow LFOs, distinct phases) — chorus on the tail, it breaks the metallic 'whistle'. Deterministic, no RNG.", "", ""};
        t["HALL"]["pre"] = LearnEntry{"Pre-delay: 0 to ~120 ms before the network. It separates the direct sound from the reverberation — what defines the perceived size.", "", ""};
        t["HALL"]["mix"] = LearnEntry{"Dry ↔ wet. 0 = straight through.", "", ""};
