        t["HALL"]["out:r"] = LearnEntry{"Right channel (odd lines) — decorrelated from L so the image comes out wide.", "", ""};
        t["LOOPER"]["time"] = LearnEntry{"Length of the delay — from a short echo to a 2 s loop.", "It is the distance between the write head and the read head in the circular buffer; changes are smoothed so it does not click.", "With FBK high, turn TIME slowly: the loop 'stretches' and 'shrinks' like tape pulled by hand."};
        t["LOOPER"]["feedback"] = LearnEntry{"How much of the output comes back into the loop — above 1 it self-oscillates.", "The fed-back signal passes through the AGE filter and through a tanh that holds the level before summing back in.", "Set it to ~1.05 with no input: the loop sustains itself and AGE becomes the timbre of the tail."};
        t["LOOPER"]["age"] = LearnEntry{"Tape/BBD character: loss of treble in the loop, wow & flutter, saturation and hiss.", "A low-pass inside the feedback darkens it at each round; two slow LFOs (~0.9 and ~6.5 Hz) modulate the read; seeded noise sums into the loop.", "Hold with HOLD and raise AGE: each repetition becomes a little darker and more tremulous, like a copy of a copy."};
        t["LOOPER"]["mix"] = LearnEntry{"Dry ↔ wet on the OUT output.", "", ""};
        t["LOOPER"]["heads"] = LearnEntry{"1 head = a simple echo. 2–4 = a MULTI-HEAD tape echo (Space Echo): the extra heads read fractions of TIME (0.75 / 0.5 / 0.25×) and sum — a dense, rhythmic echo.", "Like the playback heads of the Roland RE-201 before the erase head; the feedback regenerates them all.", "FBK close to 1 + a long TIME + several heads = dense Frippertronics."};
        t["LOOPER"]["hold"] = LearnEntry{"Freezes the loop: it stops writing and repeats the current window forever.", "On the rising edge it anchors the window at the current write position; the read then circulates only in that stretch, with no new feedback.", "Play a phrase, switch HOLD on at the end of it and improvise over the top — the stretch becomes a bed."};
        t["LOOPER"]["reverse"] = LearnEntry{"Reads the loop backwards, with no click.", "Two Hann-windowed reads, half a round out of phase, cross over (a crossfade), so the turn at the end of the buffer does not pop.", "Combine REV + HOLD: a fixed stretch playing backwards in a loop."};
