        t["HALL"]["size"] = LearnEntry{"Taille de l’espace — elle met à l’échelle les 8 longueurs de ligne, de ~8 ms (une pièce) à ~88 ms (un hall).", "C’est un réseau de retards rebouclés (FDN) : 8 lignes + une matrice de Householder (sans perte) les recombine à chaque tour. SPACE c’est comb+allpass ; ceci, c’est le réseau.", "Branchez un LFO lent sur SIZE : la salle « respire » et désaccorde la queue (effet de bande)."};
        t["HALL"]["decay"] = LearnEntry{"Temps de queue (RT60) : 0,2 s à 15 s. Près du maximum la queue ne décroît presque plus.", "Le gain de chaque ligne découle du RT60 : g = 10^(−3·temps/RT60). Householder est orthogonale, donc g < 1 décroît toujours, cela n’explose jamais.", ""};
        t["HALL"]["damp"] = LearnEntry{"Un passe-bas à l’intérieur de la boucle de chaque ligne — l’aigu décroît avant le grave, comme dans une vraie salle. 0 = brillant, 1 = sombre.", "", ""};
        t["HALL"]["mod"] = LearnEntry{"Profondeur de la modulation du point de lecture de chaque ligne (LFOs lents, phases distinctes) — chorus sur la queue, cela casse le « sifflement » métallique. Déterministe, sans RNG.", "", ""};
