        t["HALL"]["in:size"] = LearnEntry{"CV ajoutée à SIZE.", "", ""};
        t["HALL"]["in:decay"] = LearnEntry{"CV ajoutée à DECAY.", "", ""};
        t["HALL"]["in:freeze"] = LearnEntry{"Gate : tant qu’il est haut, la queue devient infinie (g = 1, le réseau conserve l’énergie) et la nouvelle entrée cesse d’entrer — comme le HOLD du LOOPER, mais pour l’espace.", "", ""};
        t["HALL"]["out:l"] = LearnEntry{"Canal gauche (combinaison des lignes paires).", "", ""};
        t["HALL"]["out:r"] = LearnEntry{"Canal droit (lignes impaires) — décorrélé du L pour que l’image soit large.", "", ""};
        t["LOOPER"]["time"] = LearnEntry{"Longueur du retard — de l’écho court à la boucle de 2 s.", "C’est la distance entre la tête d’écriture et la tête de lecture dans le tampon circulaire ; les changements sont lissés pour éviter les clics.", "Avec FBK élevé, tournez TIME lentement : la boucle « s’étire » et « se resserre » comme une bande tirée à la main."};
        t["LOOPER"]["feedback"] = LearnEntry{"Quelle part de la sortie revient dans la boucle — au-delà de 1 elle auto-oscille.", "Le signal rebouclé passe par le filtre d’AGE et par un tanh qui retient le niveau avant de le réadditionner.", "Mettez-la à ~1,05 sans entrée : la boucle se soutient et l’AGE devient le timbre de la queue."};
        t["LOOPER"]["age"] = LearnEntry{"Caractère bande/BBD : perte d’aigu dans la boucle, wow & flutter, saturation et souffle.", "Un passe-bas à l’intérieur de la rétroaction l’assombrit à chaque tour ; deux LFOs lents (~0,9 et ~6,5 Hz) modulent la lecture ; un bruit semé s’additionne dans la boucle.", "Figez avec HOLD et montez l’AGE : chaque répétition devient un peu plus sombre et tremblante, comme une copie de copie."};
        t["LOOPER"]["mix"] = LearnEntry{"Sec ↔ mouillé sur la sortie OUT.", "", ""};
        t["LOOPER"]["heads"] = LearnEntry{"1 tête = un écho simple. 2–4 = un écho à bande MULTI-TÊTES (Space Echo) : les têtes supplémentaires lisent des fractions de TIME (0,75 / 0,5 / 0,25×) et s’additionnent — un écho dense et rythmique.", "Comme les têtes de lecture du Roland RE-201 avant la tête d’effacement ; la rétroaction les régénère toutes.", "FBK près de 1 + un TIME long + plusieurs têtes = du Frippertronics dense."};
        t["LOOPER"]["hold"] = LearnEntry{"Gèle la boucle : elle cesse d’écrire et répète la fenêtre actuelle indéfiniment.", "Sur le front montant elle ancre la fenêtre à la position d’écriture actuelle ; la lecture ne circule plus que dans ce passage, sans nouvelle rétroaction.", "Jouez une phrase, activez HOLD à sa fin et improvisez par-dessus — le passage devient un fond."};
        t["LOOPER"]["reverse"] = LearnEntry{"Lit la boucle à l’envers, sans clic.", "Deux lectures en fenêtre de Hann, déphasées d’un demi-tour, se croisent (crossfade), donc le retournement en fin de tampon ne claque pas.", "Combinez REV + HOLD : un passage fixe joué à l’envers en boucle."};
        t["LOOPER"]["in:in"] = LearnEntry{"Entrée audio.", "", ""};
        t["LOOPER"]["in:time"] = LearnEntry{"CV qui s’ajoute à TIME (en secondes).", "", ""};
        t["LOOPER"]["in:freeze"] = LearnEntry{"Gate : tant qu’il est haut, cela équivaut à HOLD activé.", "", ""};
        t["LOOPER"]["in:rev"] = LearnEntry{"Gate : tant qu’il est haut, cela équivaut à REV activé.", "", ""};
