        t["LOOPER"]["out:wet"] = LearnEntry{"Seulement la boucle, sans le sec.", "", ""};
        t["SWIRL"]["type"] = LearnEntry{"0 CHORUS (2 voix, ça étoffe) · 1 FLANGER (1 retard court + rétroaction, jet/peigne) · 2 ENSEMBLE (3 voix, Juno/Solina) · 3 PHASER (cascade de all-pass, notch mobile).", "Les trois premiers sont des retards COURTS modulés ; le phaser remplace la ligne à retard par 6 all-pass du 1er ordre — timbre plus creux, moins métallique.", "Comparez FLANGER et PHASER au même RATE/DEPTH : le peigne balaie métallique, le notch balaie creux."};
        t["SWIRL"]["rate"] = LearnEntry{"Vitesse du LFO (triangulaire) qui balaie la modulation. 0,02 Hz = presque immobile ; 8 Hz = vibrato.", "", ""};
        t["SWIRL"]["depth"] = LearnEntry{"Profondeur du balayage — de combien le retard (ou la coupure des all-pass) se déplace. 0 = coloration statique.", "", ""};
        t["SWIRL"]["feedback"] = LearnEntry{"Rétroaction (−1..1). En FLANGER/PHASER elle crée la résonance (positive = peigne/notch aigu, négative = inversé). En CHORUS/ENSEMBLE un filet donne du vibrato.", "Un tanh dans la boucle retient le niveau ; près de ±1 elle auto-oscille (le mode autonome, à partir du plancher de bruit de l’AGE).", ""};
        t["SWIRL"]["tone"] = LearnEntry{"Un filtre à 1 pôle SUR le mouillé : <0 passe-bas (le « velouté » du BBD), >0 passe-haut (cela affine, retire le grave), 0 neutre.", "", ""};
        t["SWIRL"]["spread"] = LearnEntry{"Largeur stéréo : le LFO du canal R est décalé de spread·¼ de cycle par rapport au L ; sur les voix multiples il étale aussi le désaccord. 0 = mono.", "", ""};
        t["SWIRL"]["age"] = LearnEntry{"Caractère BBD (bucket-brigade) : compansion (il comprime avant la ligne, étend après), un filet de bruit semé et une pointe d’aliasing. 0 = propre.", "Déterministe — deux rendus au même AGE sont identiques à l’octet.", ""};
        t["SWIRL"]["mix"] = LearnEntry{"Sec ↔ mouillé. 0 = passage direct (un bypass exact).", "", ""};
