        t["MEMORY"]["feedback"] = LearnEntry{"Réinjecte la sortie dans le tampon avant l’enregistrement — le matériau s’accumule/dégénère.", "", ""};
        t["MEMORY"]["blend"] = LearnEntry{"Sec (entrée brute) ↔ mouillé (le nuage de grains).", "", ""};
        t["MEMORY"]["freeze"] = LearnEntry{"Arrête l’enregistrement — le tampon devient une texture fixe, seuls les grains continuent de relire.", "", "Activez FREEZE au milieu d’une phrase : le matériau capturé devient une boucle granulaire statique, sans aucun gate à tenir."};
        t["MEMORY"]["in:in"] = LearnEntry{"Entrée audio, enregistrée en continu dans le tampon (sauf avec FREEZE).", "", ""};
