        t["MEMORY"]["in:pitch_mod"] = LearnEntry{"CV 1 V/oct qui s’ajoute à PITCH (en octaves).", "", ""};
        t["MEMORY"]["in:freeze_gate"] = LearnEntry{"Gate — un niveau haut gèle le tampon, comme l’interrupteur HOLD.", "", ""};
        t["MEMORY"]["out:out"] = LearnEntry{"Mélange entre l’entrée brute et le nuage de grains.", "", ""};
        t["SAMPLER"]["start"] = LearnEntry{"Point de départ de la lecture, à l’intérieur de la tranche sélectionnée (0 = début, 1 = fin).", "", ""};
        t["SAMPLER"]["speed"] = LearnEntry{"Varispeed bipolaire : signe·2^(|speed|·2) → ±0,25× à ±4×. Négatif = lecture à l’envers.", "Sans REPIT, la vitesse et la hauteur avancent ensemble (comme un magnétophone). 2× plus vite = une octave au-dessus.", "Branchez SEQUENCE → PIT et jouez la même tranche à plusieurs hauteurs."};
        t["SAMPLER"]["slices"] = LearnEntry{"Divise le tampon enregistré en N tranches égales (1–16). La CV de POS choisit laquelle déclencher.", "C’est le « chop » du MPC — enregistrez une mesure, coupez-la en 8, déclenchez les tranches dans le désordre depuis un TRIGSEQ.", ""};
        t["SAMPLER"]["repitch"] = LearnEntry{"0 = la transposition (PIT) change la vitesse (varispeed). 1 = la vitesse est laissée libre et la hauteur vient d’un pitch-shifter (la durée de la tranche est préservée).", "Le pitch-shifter est celui du G09.pitchshift.pd de Pure Data, porté depuis Navalha 2 (crédit : Glerm Soares / Lúcio Araújo).", ""};
        t["SAMPLER"]["wear"] = LearnEntry{"Usure par déclenchement : jitter au point de départ, réduction du taux d’échantillonnage et bit-crush qui croissent avec le potentiomètre. Chaque déclenchement sonne un peu différemment.", "Déterministe — un xorshift semé SUR le déclenchement, donc la même suite de triggers donne le même audio.", ""};
        t["SAMPLER"]["loop"] = LearnEntry{"One-shot (éteint) ↔ boucle de la tranche (allumé). Le point de boucle n’a pas encore de crossfade — il peut claquer sur une tranche très courte.", "", ""};
        t["SAMPLER"]["in:trig"] = LearnEntry{"Déclenche la tranche actuelle.", "", ""};
        t["SAMPLER"]["in:in"] = LearnEntry{"Audio à enregistrer (tant que REC est haut).", "", ""};
        t["SAMPLER"]["in:rec"] = LearnEntry{"Gate : tant qu’il est haut, il enregistre IN dans le tampon (jusqu’à ~8 s). Au front descendant, il gèle la longueur enregistrée.", "Sans enregistrement et sans fichier chargé depuis le panneau, le SAMPLER reste silencieux.", ""};
        t["SAMPLER"]["in:pos"] = LearnEntry{"CV (0–1) qui choisit la tranche.", "", ""};
