        t["HALL"]["size"] = LearnEntry{"Tamaño del espacio — escala las 8 longitudes de línea de ~8 ms (una sala) a ~88 ms (un hall).", "Es una red de retardos realimentada (FDN): 8 líneas + una matriz de Householder (sin pérdida) las recombina en cada vuelta. SPACE es comb+allpass; esto es la red.", "Cablee un LFO lento en SIZE: la sala 'respira' y desafina la cola (efecto de cinta)."};
        t["HALL"]["decay"] = LearnEntry{"Tiempo de cola (RT60): 0,2 s a 15 s. Cerca del máximo la cola casi no decae.", "La ganancia de cada línea sale del RT60: g = 10^(−3·tiempo/RT60). Householder es ortogonal, así que g < 1 siempre decae, nunca explota.", ""};
        t["HALL"]["damp"] = LearnEntry{"Un paso bajo dentro del lazo de cada línea — el agudo decae antes que el grave, como en una sala real. 0 = brillante, 1 = oscuro.", "", ""};
        t["HALL"]["mod"] = LearnEntry{"Profundidad de la modulación del punto de lectura de cada línea (LFOs lentos, fases distintas) — chorus en la cola, rompe el 'pitido' metálico. Determinista, sin RNG.", "", ""};
        t["HALL"]["pre"] = LearnEntry{"Pre-retardo: 0 a ~120 ms antes de la red. Separa el sonido directo de la reverberación — lo que define el tamaño percibido.", "", ""};
