        t["LOOPER"]["time"] = LearnEntry{"Longitud del retardo — de eco corto a lazo de 2 s.", "Es la distancia entre el cabezal de escritura y el de lectura en el búfer circular; los cambios se suavizan para que no chasquee.", "Con FBK alto, gire TIME despacio: el lazo se 'estira' y se 'encoge' como cinta tirada a mano."};
        t["LOOPER"]["feedback"] = LearnEntry{"Cuánto de la salida vuelve al lazo — por encima de 1 autooscila.", "La señal realimentada pasa por el filtro de AGE y por un tanh que retiene el nivel antes de volver a sumarse.", "Póngala en ~1,05 sin entrada: el lazo se sostiene y el AGE se vuelve el timbre de la cola."};
        t["LOOPER"]["age"] = LearnEntry{"Carácter de cinta/BBD: pérdida de agudo en el lazo, wow & flutter, saturación y siseo.", "Un paso bajo dentro de la realimentación oscurece en cada vuelta; dos LFO lentos (~0,9 y ~6,5 Hz) modulan la lectura; un ruido sembrado se suma al lazo.", "Sostenga con HOLD y suba el AGE: cada repetición queda un poco más oscura y trémula, como copia de copia."};
        t["LOOPER"]["mix"] = LearnEntry{"Seco ↔ mojado en la salida OUT.", "", ""};
        t["LOOPER"]["heads"] = LearnEntry{"1 cabezal = eco simple. 2–4 = eco de cinta MULTICABEZAL (Space Echo): los cabezales extra leen fracciones de TIME (0,75 / 0,5 / 0,25×) y suman — eco denso y rítmico.", "Como los cabezales de reproducción del Roland RE-201 antes del cabezal de borrado; la realimentación los regenera todos.", "FBK cerca de 1 + TIME largo + varios cabezales = Frippertronics denso."};
        t["LOOPER"]["hold"] = LearnEntry{"Congela el lazo: deja de escribir y repite la ventana actual para siempre.", "En el flanco de subida ancla la ventana en la posición de escritura actual; la lectura pasa a circular sólo en ese tramo, sin realimentación nueva.", "Toque una frase, active HOLD al final de ella e improvise encima — el tramo se vuelve base."};
        t["LOOPER"]["reverse"] = LearnEntry{"Lee el lazo al revés, sin clic.", "Dos lecturas en ventana de Hann desfasadas media vuelta se cruzan (crossfade), así que el giro al final del búfer no chasquea.", "Combine REV + HOLD: un tramo fijo sonando al revés en bucle."};
