        t["SWIRL"]["type"] = LearnEntry{"0 CHORUS (2 voces, engorda) · 1 FLANGER (1 retardo corto + realimentación, chorro/peine) · 2 ENSEMBLE (3 voces, Juno/Solina) · 3 PHASER (cascada de all-pass, notch móvil).", "Los tres primeros son retardos CORTOS modulados; el phaser cambia la línea de retardo por 6 all-pass de 1.er orden — timbre más hueco, menos metálico.", "Compare FLANGER y PHASER con el mismo RATE/DEPTH: el peine barre metálico, el notch barre hueco."};
        t["SWIRL"]["rate"] = LearnEntry{"Velocidad del LFO (triangular) que barre la modulación. 0,02 Hz = casi quieto; 8 Hz = vibrato.", "", ""};
