        t["SWIRL"]["feedback"] = LearnEntry{"Realimentación (−1..1). En FLANGER/PHASER crea la resonancia (positiva = peine/notch agudo, negativa = invertido). En CHORUS/ENSEMBLE un hilo da vibrato.", "Un tanh en el lazo retiene el nivel; cerca de ±1 autooscila (el modo autónomo, a partir del suelo de ruido del AGE).", ""};
        t["SWIRL"]["tone"] = LearnEntry{"Un filtro de 1 polo EN el mojado: <0 paso bajo (lo 'aterciopelado' del BBD), >0 paso alto (afina, quita el grave), 0 neutro.", "", ""};
        t["SWIRL"]["spread"] = LearnEntry{"Anchura estéreo: el LFO del canal R se desfasa spread·¼ de ciclo respecto al L; en las voces múltiples también esparce el desafine. 0 = mono.", "", ""};
        t["SWIRL"]["age"] = LearnEntry{"Carácter BBD (bucket-brigade): compansión (comprime antes de la línea, expande después), un hilo de ruido sembrado y una pizca de aliasing. 0 = limpio.", "Determinista — dos renders con el mismo AGE son idénticos byte a byte.", ""};
        t["SWIRL"]["mix"] = LearnEntry{"Seco ↔ mojado. 0 = paso directo (bypass exacto).", "", ""};
        t["SWIRL"]["in:in"] = LearnEntry{"Audio a procesar.", "", ""};
        t["SWIRL"]["in:rate_mod"] = LearnEntry{"CV sumada a RATE (barrido fuera del compás).", "", ""};
        t["SWIRL"]["in:mix_mod"] = LearnEntry{"CV sumada a MIX (el efecto entra en el ataque/la cola, vía un ENVELOPE).", "", ""};
