        t["MEMORY"]["pitch"] = LearnEntry{"Transposición de la lectura de los granos, en semitonos (±24).", "", ""};
        t["MEMORY"]["feedback"] = LearnEntry{"Realimenta la salida de vuelta al búfer antes de grabar — el material se acumula/degenera.", "", ""};
        t["MEMORY"]["blend"] = LearnEntry{"Seco (entrada cruda) ↔ mojado (la nube de granos).", "", ""};
        t["MEMORY"]["freeze"] = LearnEntry{"Detiene la grabación — el búfer se vuelve una textura fija, sólo los granos siguen releyendo.", "", "Active FREEZE en medio de una frase: el material capturado se vuelve un bucle granular estático, sin tener que sostener ningún gate."};
        t["MEMORY"]["in:in"] = LearnEntry{"Entrada de audio, grabada continuamente en el búfer (excepto con FREEZE).", "", ""};
