        t["MEMORY"]["in:pitch_mod"] = LearnEntry{"CV 1 V/oct que se suma a PITCH (en octavas).", "", ""};
        t["MEMORY"]["in:freeze_gate"] = LearnEntry{"Gate — un nivel alto congela el búfer, igual que el interruptor HOLD.", "", ""};
        t["MEMORY"]["out:out"] = LearnEntry{"Mezcla entre la entrada cruda y la nube de granos.", "", ""};
        t["SAMPLER"]["start"] = LearnEntry{"Punto de partida de la reproducción, dentro de la rodaja seleccionada (0 = principio, 1 = final).", "", ""};
        t["SAMPLER"]["speed"] = LearnEntry{"Varispeed bipolar: signo·2^(|speed|·2) → ±0,25× a ±4×. Negativo = tocar al revés.", "Sin REPIT, la velocidad y la altura van juntas (como un magnetófono). 2× más rápido = una octava arriba.", "Cablee SEQUENCE → PIT y toque la misma rodaja en varias alturas."};
        t["SAMPLER"]["slices"] = LearnEntry{"Divide el búfer grabado en N rodajas iguales (1–16). La CV de POS elige cuál disparar.", "Es el 'chop' del MPC — grabe un compás, córtelo en 8, dispare las rodajas desordenadas desde un TRIGSEQ.", ""};
        t["SAMPLER"]["repitch"] = LearnEntry{"0 = la transposición (PIT) cambia la velocidad (varispeed). 1 = la velocidad queda libre y la altura viene de un pitch-shifter (se preserva la duración de la rodaja).", "El pitch-shifter es el de G09.pitchshift.pd de Pure Data, portado desde Navalha 2 (crédito: Glerm Soares / Lúcio Araújo).", ""};
        t["SAMPLER"]["wear"] = LearnEntry{"Desgaste por disparo: jitter en el punto de inicio, reducción de la tasa de muestreo y bit-crush que crecen con el mando. Cada disparo suena un poco distinto.", "Determinista — un xorshift sembrado EN el disparo, así que la misma secuencia de triggers da el mismo audio.", ""};
        t["SAMPLER"]["loop"] = LearnEntry{"One-shot (apagado) ↔ bucle de la rodaja (encendido). El punto de bucle aún no tiene crossfade — puede chasquear en una rodaja muy corta.", "", ""};
