        t["SAMPLER"]["out:out"] = LearnEntry{"La rodaja tocada, con de-click adaptativo en los bordes.", "", ""};
        t["TURNTABLE"]["speed"] = LearnEntry{"Velocidad objetivo del plato: signo·2^|speed| → ±0,5× a ±2× (33⅓ ↔ 45 ↔ lento). Negativo = el disco girando al revés.", "Es sólo el OBJETIVO — el plato tiene masa y tarda en llegar allí (ver TORQ).", "Negativo + BRK: el disco desacelera de −2× hasta parar, 'subiendo' de afinación por el camino."};
        t["TURNTABLE"]["torque"] = LearnEntry{"Fuerza del motor: con qué rapidez el plato ALCANZA la velocidad. Baja = un 'wow' largo de arranque (~1 s); alta = casi instantáneo.", "Constante de tiempo de un sistema de 1.er orden: motorCoef = 0,00002 + torque²·0,0022.", "TORQ al mínimo: el motor apenas tira — el plato sólo anda si la mano (SCR) lo empuja. Modo 'vinilo sin motor'."};
        t["TURNTABLE"]["friction"] = LearnEntry{"Roce: con qué rapidez el plato para en BRK (deriva corta o larga) y cuánto 'vuelve' solo después de un scratch.", "", ""};
        t["TURNTABLE"]["grab"] = LearnEntry{"Firmeza de la mano: cuánto lanza la CV SCR al plato. Un SCR pequeño = pitch-bend (un empujoncito para el beatmatch); un SCR grande y oscilante = un scratch de verdad.", "grip = clamp01(|scratch|·5)·grab; la mano tira la velocidad hacia scratch·4 con un acoplamiento de ·0,3.", "La mano actúa incluso con el motor parado — LFO → SCR hace que el disco rasque en compás sin ningún trigger."};
        t["TURNTABLE"]["start"] = LearnEntry{"Dónde cae la aguja (la posición en el disco) en el flanco de subida de TRIG.", "", ""};
        t["TURNTABLE"]["wear"] = LearnEntry{"Desgaste del vinilo: chasquidos/clics que crecen + leve inestabilidad de rotación + caída mínima de nivel.", "Determinista — xorshift sembrado; wear=0 anula el término. Dos renders con los mismos parámetros son idénticos byte a byte.", ""};
        t["TURNTABLE"]["loop"] = LearnEntry{"One-shot (el disco 'acaba' y se traba en la última muestra) ↔ surco cerrado (la lectura da la vuelta al búfer).", "", ""};
        t["TURNTABLE"]["in:trig"] = LearnEntry{"Pone la aguja: readPos = START·longitud, rampa de ~5 ms (sin clic) y ENCIENDE el motor. Después del 1.er trig el motor queda encendido.", "", ""};
        t["TURNTABLE"]["in:in"] = LearnEntry{"Audio a grabar (mientras REC esté alto).", "", ""};
        t["TURNTABLE"]["in:rec"] = LearnEntry{"Gate: mientras está alto, graba IN en el búfer (hasta ~8 s). En el flanco de bajada, congela la longitud — no se puede tocar y grabar a la vez.", "Sin grabar y sin archivo cargado desde el panel, el TURNTABLE queda en silencio.", ""};
        t["TURNTABLE"]["in:scratch"] = LearnEntry{"La mano, como CV bipolar. Un LFO y la mano de un DJ son intercambiables aquí.", "handTgt = scratch·4 (±4× la velocidad); la firmeza viene de GRAB.", "SEQUENCE → SCR: una frase de scratch rítmica. ENVELOPE → BRK: un tape-stop en el remate."};
        t["TURNTABLE"]["in:brake"] = LearnEntry{"Gate: mientras está alto, el motor suelta y el plato para (una deriva gobernada por FRIC). Suelte el gate y el motor lo trae de vuelta.", "", ""};
        t["TURNTABLE"]["out:out"] = LearnEntry{"El material grabado leído por el plato, con acoplamiento AC (sin escalón de DC cuando el plato para).", "", ""};
