        t["FILTER"]["cutoff"] = LearnEntry{"Cutoff frequency — above it, the sound is attenuated.", "A subtractive filter takes energy away above (or near) the cutoff; below it the signal passes almost unchanged.", "Turn it slowly and hear the timbre darken. Then connect ENVELOPE.env to FC — the cutoff opens on its own at every note."};
        t["FILTER"]["resonance"] = LearnEntry{"Lifts the frequencies near the cutoff.", "High resonance pushes the filter close to self-oscillation — it starts to sound almost like an oscillator.", "Raise RESO close to maximum with CUT on a low note: the filter starts singing on its own, even with no input."};
