        t["FILTER"]["drive"] = LearnEntry{"Input gain — it pushes the signal into gentle saturation.", "It saturates BEFORE the filter: bass that comes in saturated changes what is left to filter.", "Raise DRIVE with a low CUT: the bass fattens before it is cut."};
