        t["FORMANT"]["vowel"] = LearnEntry{"Position in the vowel sequence A → E → I → O → U. Each vowel is a set of 5 formants (spectral peaks); the knob interpolates between the neighbours.", "Source-filter theory (Fant): the voice is a source × the vocal tract's filter; the vowel is where the 5 formants are. Phonetic data from a bass voice.", "Patch SEQUENCE → VOW: a melody of vowels over a drone."};
        t["FORMANT"]["shift"] = LearnEntry{"Scales ALL the formant frequencies (2^(shift·1.5), ≈ 0.35× to 2.8×) — the length of the vocal tract: down = a big/low voice, up = a small/high voice.", "It is the formant shift — it changes the voice's timbre without changing the source's pitch.", ""};
        t["FORMANT"]["res"] = LearnEntry{"Narrows the 5 bands (width ÷ (1 + res·8)). 0 = a subtle colouration; 1 = bands that sing/whistle.", "Q = frequency ÷ bandwidth. With res high and noise at the input, each vowel becomes 5 sine tones.", "ENVELOPE → RES: the voice 'tightens' on the attack and relaxes."};
        t["FORMANT"]["mix"] = LearnEntry{"Dry ↔ resonated. 0 = straight through.", "", ""};
        t["FORMANT"]["drift"] = LearnEntry{"Each formant gets a slow, independent wobble (±drift·3 %) — the voice breathes. Deterministic (sines, no RNG). 0 = static.", "", ""};
        t["FORMANT"]["vocoder"] = LearnEntry{"Blends towards VOCODER mode: the GAINS of the 5 bands start following the energy of the MODULATOR (the MOD jack) at each formant frequency, instead of the vowel table. 0 = classic FORMANT; 1 = a 5-band vocoder.", "Homer Dudley's vocoder (1938): (modulator → a bank of per-band envelope followers) × (carrier → a filter bank). Here the 5 formant bands are the vocoder's bands — coarse but vocalic. With no MOD patched, it has no effect.", "Speech into MOD, a rich OSC/PAD into IN, VOCODER=1: the pad 'speaks'. VOWEL chooses WHICH 5 frequencies get vocoded."};
        t["FORMANT"]["in:in"] = LearnEntry{"The CARRIER — what is going to be shaped (a saw OSC, a pad, NOISE). In vocoder mode it is the 'synthetic' voice that speaks.", "", ""};
        t["FORMANT"]["in:vowel"] = LearnEntry{"CV added to VOWEL (an LFO, a SEQUENCE, an envelope…).", "", ""};
        t["FORMANT"]["in:shift"] = LearnEntry{"CV added to SHIFT.", "", ""};
        t["FORMANT"]["in:mod"] = LearnEntry{"The vocoder's MODULATOR — the sound whose spectral envelope will control the 5 bands (a voice, a DRUM, a recording). It only has an effect with VOCODER > 0.", "", ""};
        t["FORMANT"]["out:out"] = LearnEntry{"Dry + the 5 bands, mixed by MIX, with a gentle limiter.", "", ""};
        t["VOCODER"]["bands"] = LearnEntry{"How many frequency bands (4–20). Few = a coarse 'robot'; many (16–20) = intelligible speech.", "Homer Dudley's vocoder (1938): the MODULATOR's per-band energy controls the gain of the same band on the CARRIER. `FORMANT` does the same with 5 vowel bands; this is the dedicated, wide-band vocoder.", "A voice into MOD, a pad/saw into CAR, BANDS=16: the pad speaks. BANDS=6 = the vocoder of the 70s."};
        t["VOCODER"]["shift"] = LearnEntry{"Shifts the SYNTHESIS frequencies relative to the analysis (2^(shift·1.2)) — a formant shift: up = a small voice, down = a big voice, without changing the speech.", "", "LFO → nothing (it is not an input); move it by hand for a voice that 'grows' across the phrase."};
        t["VOCODER"]["sibilance"] = LearnEntry{"How much of the modulator's TREBLE (> ~3.5 kHz) passes STRAIGHT through — the fricatives (s, f, sh) that band analysis does not catch. 0 = a lisp; high = crisp speech.", "", ""};
        t["VOCODER"]["attack"] = LearnEntry{"Attack of the envelope followers (1–60 ms). Short = the consonants cut dry; long = everything softens.", "", ""};
        t["VOCODER"]["release"] = LearnEntry{"Release (20–600 ms). Short = staccato/intelligible; long = the syllables blur into one another (a spoken pad).", "", ""};
        t["VOCODER"]["mix"] = LearnEntry{"Dry carrier ↔ vocoded. 0 = bypass.", "", ""};
