        t["CRUSH"]["bits"] = LearnEntry{"Quantises the amplitude to 2^bits levels (round(x·L)/L). bits=1 ≈ a square wave; bits=16 ≈ transparent.", "", "ENVELOPE → BITS: the resolution drops in the tail of the note."};
