        t["CRUSH"]["wrap"] = LearnEntry{"How the signal that goes past ±1 behaves: 0 CLIPS (it limits), 1 WRAPS (mod(x+1,2)−1 — integer overflow, a brutal sawtooth), between the two a blend.", "With a high DRIVE + WRAP=1 the signal wraps several times → harmonics up to Nyquist, it aliases (accepted — it is the effect).", ""};
        t["CRUSH"]["glitch"] = LearnEntry{"Probability, per hold-sample, of a FAULT: a stuck sample (it stays at the previous value), a dropout (silence) or a spike (the previous one amplified). It simulates a bad digital connection / a scratched CD.", "Seeded (xorshift) — the same patch sounds the same twice. REPRODUCIBLE damage, unlike a bug.", ""};
