        t["GLIDE"]["curve"] = LearnEntry{"Shape of the glide: 0 = linear (constant speed, it arrives at the exact time — MS-20/Minimoog); 1 = exponential (RC, it drags at the arrival).", "The same slope at the start; the exponential decelerates and only touches the target after ~3 TIME.", ""};
        t["GLIDE"]["mode"] = LearnEntry{"0 = it always glides (classic portamento); 1 = only while SLIDE is high (the TB-303's slide, each step decides); 2 = legato (it glides only if GATE stays high through the change; a new gate jumps).", "", ""};
