        t["FILTER"]["cutoff"] = LearnEntry{"Fréquence de coupure — au-dessus d’elle, le son est atténué.", "Un filtre soustractif retire de l’énergie au-dessus (ou près) de la coupure ; en dessous le signal passe presque inchangé.", "Tournez-le lentement et écoutez le timbre s’assombrir. Puis branchez ENVELOPE.env sur FC — la coupure s’ouvre toute seule à chaque note."};
        t["FILTER"]["resonance"] = LearnEntry{"Relève les fréquences près de la coupure.", "Une résonance élevée pousse le filtre près de l’auto-oscillation — il se met à sonner presque comme un oscillateur.", "Montez RESO près du maximum avec CUT sur une note grave : le filtre commence à chanter tout seul, même sans entrée."};
        t["FILTER"]["spread"] = LearnEntry{"Écarte les 3 sorties (low/center/high) sur des fréquences différentes.", "Ce sont 3 filtres « frères » sur la même base, écartés par SPRD — cela donne un corps multimode sans avoir besoin de 3 modules.", "Comparez la sortie ALL avec SPRD=0 (un seul filtre) et SPRD=1 (trois bien séparés)."};
        t["FILTER"]["drive"] = LearnEntry{"Gain d’entrée — il pousse le signal vers une saturation douce.", "Il sature AVANT le filtre : un grave qui entre saturé change ce qu’il reste à filtrer.", "Montez DRIVE avec un CUT bas : le grave s’étoffe avant d’être coupé."};
        t["FILTER"]["in:in"] = LearnEntry{"Entrée audio à filtrer.", "", ""};
        t["FILTER"]["in:cutoff_mod"] = LearnEntry{"CV (1 V/oct) qui S’AJOUTE au potentiomètre CUT.", "Le câble module la coupure par-dessus la valeur du potentiomètre — tourner CUT fonctionne toujours avec le câble branché (moteur additif).", ""};
