        t["FILTER"]["out:high"] = LearnEntry{"Sortie aiguë isolée (passe-haut).", "", ""};
        t["FILTER"]["out:all"] = LearnEntry{"La somme des 3 sorties — la plus utilisée pour sortir du filtre.", "", ""};
        t["FORMANT"]["vowel"] = LearnEntry{"Position dans la suite de voyelles A → E → I → O → U. Chaque voyelle est un ensemble de 5 formants (pics spectraux) ; le potentiomètre interpole entre les voisines.", "Théorie source-filtre (Fant) : la voix est une source × le filtre du conduit vocal ; la voyelle est l’endroit où se trouvent les 5 formants. Données phonétiques d’une voix de basse.", "Branchez SEQUENCE → VOW : une mélodie de voyelles sur un drone."};
        t["FORMANT"]["shift"] = LearnEntry{"Met à l’échelle TOUTES les fréquences de formant (2^(shift·1,5), ≈ 0,35× à 2,8×) — la longueur du conduit vocal : vers le bas = voix grande/grave, vers le haut = voix petite/aiguë.", "C’est le formant shift — il change le timbre de la voix sans changer la hauteur de la source.", ""};
        t["FORMANT"]["res"] = LearnEntry{"Resserre les 5 bandes (largeur ÷ (1 + res·8)). 0 = une coloration subtile ; 1 = des bandes qui chantent/sifflent.", "Q = fréquence ÷ largeur de bande. Avec res élevé et du bruit à l’entrée, chaque voyelle devient 5 sons sinusoïdaux.", "ENVELOPE → RES : la voix se « serre » à l’attaque puis se relâche."};
        t["FORMANT"]["mix"] = LearnEntry{"Sec ↔ résonné. 0 = passage direct.", "", ""};
        t["FORMANT"]["drift"] = LearnEntry{"Chaque formant reçoit un wobble lent et indépendant (±drift·3 %) — la voix respire. Déterministe (des sinus, sans RNG). 0 = statique.", "", ""};
        t["FORMANT"]["vocoder"] = LearnEntry{"Fait passer au mode VOCODER : les GAINS des 5 bandes se mettent à suivre l’énergie du MODULATEUR (le jack MOD) à chaque fréquence de formant, au lieu de la table de voyelle. 0 = FORMANT classique ; 1 = un vocodeur à 5 bandes.", "Vocodeur de Homer Dudley (1938) : (modulateur → un banc de suiveurs d’enveloppe par bande) × (porteuse → un banc de filtres). Ici les 5 bandes de formant sont les bandes du vocodeur — grossier mais vocalique. Sans MOD câblé, aucun effet.", "De la parole dans MOD, un OSC/PAD riche dans IN, VOCODER=1 : le pad « parle ». VOWEL choisit QUELLES 5 fréquences sont vocodées."};
        t["FORMANT"]["in:in"] = LearnEntry{"La PORTEUSE — ce qui va être façonné (un OSC scie, un pad, NOISE). En mode vocodeur c’est la voix « synthétique » qui parle.", "", ""};
        t["FORMANT"]["in:vowel"] = LearnEntry{"CV ajoutée à VOWEL (un LFO, un SEQUENCE, une enveloppe…).", "", ""};
        t["FORMANT"]["in:shift"] = LearnEntry{"CV ajoutée à SHIFT.", "", ""};
        t["FORMANT"]["in:mod"] = LearnEntry{"Le MODULATEUR du vocodeur — le son dont l’enveloppe spectrale va contrôler les 5 bandes (une voix, un DRUM, un enregistrement). Il n’a d’effet qu’avec VOCODER > 0.", "", ""};
        t["FORMANT"]["out:out"] = LearnEntry{"Sec + les 5 bandes, mélangés par MIX, avec un limiteur doux.", "", ""};
        t["VOCODER"]["bands"] = LearnEntry{"Combien de bandes de fréquence (4–20). Peu = un « robot » grossier ; beaucoup (16–20) = de la parole intelligible.", "Vocodeur de Homer Dudley (1938) : l’énergie par bande du MODULATEUR contrôle le gain de la même bande sur la PORTEUSE. Le `FORMANT` fait la même chose avec 5 bandes de voyelle ; celui-ci est le vocodeur dédié, à large bande.", "Une voix dans MOD, un pad/scie dans CAR, BANDS=16 : le pad parle. BANDS=6 = le vocodeur des années 70."};
        t["VOCODER"]["shift"] = LearnEntry{"Décale les fréquences de la SYNTHÈSE par rapport à l’analyse (2^(shift·1,2)) — formant shift : vers le haut = petite voix, vers le bas = grande voix, sans changer la parole.", "", "LFO → rien (ce n’est pas une entrée) ; bougez-le à la main pour une voix qui « grandit » au fil de la phrase."};
        t["VOCODER"]["sibilance"] = LearnEntry{"Quelle part de l’AIGU du modulateur (> ~3,5 kHz) passe DIRECTEMENT — les fricatives (s, f, ch) que l’analyse par bandes ne capte pas. 0 = un cheveu sur la langue ; élevé = parole nette.", "", ""};
        t["VOCODER"]["attack"] = LearnEntry{"Attaque des suiveurs d’enveloppe (1–60 ms). Courte = les consonnes coupent sec ; longue = tout s’adoucit.", "", ""};
