        t["VOCODER"]["in:carrier"] = LearnEntry{"La PORTEUSE — ce qui va « parler » (une scie riche, un pad, un accord, du bruit). Laissée libre → une scie interne accordable par PIT.", "", ""};
        t["VOCODER"]["in:mod"] = LearnEntry{"Le MODULATEUR — la voix/la parole (ou un DRUM, ou tout son rythmique) dont l’enveloppe spectrale façonne la porteuse.", "", ""};
