        t["SHIFTER"]["shift"] = LearnEntry{"Déplace le spectre ENTIER de tant de HERTZ (−2000..2000, +CV sur SFT : 1 unité = 1000 Hz). 0 = passage direct. Comme le décalage est en Hz et non en rapport, les partiels cessent d’être harmoniques → métallique, cloche.", "Décaleur de fréquence (SSB — bande latérale unique) : différent du ring-mod du SHAPE, qui donne les DEUX bandes (somme et différence) symétriques. Ici `up` = spectre + shift, `down` = spectre − shift, chacun sur sa sortie.", "Un Δf petit (5–20 Hz) = un « phaser » qui ne se referme jamais (les deux copies battent lentement). Un Δf grand = un fracas inharmonique."};
        t["SHIFTER"]["feedback"] = LearnEntry{"Une partie de la sortie `up` revient à l’entrée → le spectre remonte, encore et encore : un glissando infini (le « barber pole » / shimmer de Shepard). Un `feedback` négatif tire depuis `down` (il descend sans fin). Un `tanh` dans la boucle — cela n’explose jamais.", "", "SHIFT ~8 Hz + FEEDBACK ~0,8 = la corde de Risset qui monte éternellement."};
        t["SHIFTER"]["tone"] = LearnEntry{"Incline le mouillé (1 pôle) : <0 il atténue l’aigu du signal décalé, >0 il le relève. 0 = neutre.", "", ""};
        t["SHIFTER"]["drift"] = LearnEntry{"Wobble lent et SEMÉ dans le Δf (±drift·50 %) — le décalage « respire », jamais fixe. Déterministe. 0 = statique.", "", ""};
        t["SHIFTER"]["mix"] = LearnEntry{"Sec (IN) ↔ décalé, sur les DEUX sorties. 0 = bypass.", "", ""};
        t["SHIFTER"]["in:in"] = LearnEntry{"Le son à décaler — une voix, un accord, un pad.", "", ""};
        t["SHIFTER"]["in:shift_mod"] = LearnEntry{"CV ajoutée à SHIFT, en Hz (1 unité = 1000 Hz). Un LFO → un vibrato de spectre.", "", ""};
        t["SHIFTER"]["out:up"] = LearnEntry{"Spectre + SHIFT (la bande latérale supérieure).", "", ""};
        t["SHIFTER"]["out:down"] = LearnEntry{"Spectre − SHIFT (la bande inférieure). Branchez les deux vers des destinations différentes — la relation entre elles est le processus.", "", ""};
        t["CRUSH"]["rate"] = LearnEntry{"Taux du sample-and-hold interne (100 Hz–24 kHz, +CV). Bas = un escalier grossier + un aliasing fort (la « voix de robot » 8-bit) — il n’y a PAS de filtre anti-alias, l’aliasing EST le son.", "", "LFO → RATE balaie le taux : le « mange-bande à l’envers »."};
        t["CRUSH"]["bits"] = LearnEntry{"Quantifie l’amplitude à 2^bits niveaux (round(x·L)/L). bits=1 ≈ une onde carrée ; bits=16 ≈ transparent.", "", "ENVELOPE → BITS : la résolution chute dans la queue de la note."};
        t["CRUSH"]["drive"] = LearnEntry{"Gain AVANT la quantification — il pousse le signal vers le débordement (voir WRAP).", "", ""};
        t["CRUSH"]["wrap"] = LearnEntry{"Comment se comporte le signal qui dépasse ±1 : 0 ÉCRÊTE (il limite), 1 ENROULE (mod(x+1,2)−1 — le débordement d’entier, une dent de scie brutale), entre les deux un mélange.", "Avec un DRIVE élevé + WRAP=1 le signal s’enroule plusieurs fois → des harmoniques jusqu’à Nyquist, cela aliase (accepté — c’est l’effet).", ""};
        t["CRUSH"]["glitch"] = LearnEntry{"Probabilité, par échantillon de maintien, d’un DÉFAUT : un échantillon bloqué (il reste à la valeur précédente), un dropout (silence) ou un pic (le précédent amplifié). Cela simule une mauvaise connexion numérique / un CD rayé.", "Semé (xorshift) — le même patch sonne pareil deux fois. Des dégâts REPRODUCTIBLES, contrairement à un bug.", ""};
        t["CRUSH"]["jitter"] = LearnEntry{"Instabilité du taux du S&H — l’horloge tremble → instabilité de hauteur (le « wow » numérique). Semé.", "", ""};
        t["CRUSH"]["tone"] = LearnEntry{"Un filtre à 1 pôle en sortie (le filtre de reconstruction, ou son absence) : <0 passe-bas (docile), >0 passe-haut (seulement les déchets aigus), 0 neutre.", "", ""};
        t["CRUSH"]["mix"] = LearnEntry{"Sec ↔ détruit. 0 = passage direct (un bypass exact).", "", ""};
        t["CRUSH"]["in:in"] = LearnEntry{"Audio à détruire. Débranchée + MIX>0 → le S&H échantillonne son propre bruit blanc → une source de bruit lo-fi/glitch.", "", ""};
        t["CRUSH"]["in:rate_mod"] = LearnEntry{"CV ajoutée à RATE.", "", ""};
        t["CRUSH"]["in:mix_mod"] = LearnEntry{"CV ajoutée à MIX (les dégâts entrent par doses, via une ENVELOPE).", "", ""};
        t["CRUSH"]["out:out"] = LearnEntry{"Le signal détruit, mélangé au sec par MIX. Clamp de sécurité à ±4.", "", ""};
        t["PARAMETRIC"]["type1"] = LearnEntry{"Type de l’étage 1 : éteint / coupe-bas / shelf grave / cloche (peak) / shelf aigu / coupe-haut.", "", ""};
        t["PARAMETRIC"]["freq1"] = LearnEntry{"Fréquence centrale de l’étage 1.", "", ""};
        t["PARAMETRIC"]["gain1"] = LearnEntry{"Gain de l’étage 1 — il n’affecte que les shelfs et la cloche, les coupes n’ont pas de gain.", "", ""};
        t["PARAMETRIC"]["q1"] = LearnEntry{"Q de l’étage 1 — il contrôle la largeur sur la cloche, réinterprété comme « slope S » sur les shelfs (formule RBJ).", "", ""};
        t["PARAMETRIC"]["slope1"] = LearnEntry{"Pente de la coupe de l’étage 1 : 12/24/48 dB/octave (1/2/4 biquads en cascade ; n’affecte que les types de coupe).", "", ""};
        t["PARAMETRIC"]["type2"] = LearnEntry{"Type de l’étage 2 (les mêmes options que TYPE1).", "", ""};
