        t["WASP"]["out:out"] = LearnEntry{"Salida filtrada/recortada.", "", ""};
        t["LPG"]["mode"] = LearnEntry{"Crossfade filtro↔VCA — 0 sólo filtro, 1 sólo VCA, 0,5 los dos totalmente activos (el LPG clásico, se cierra del todo cuando la envolvente cae a 0).", "", ""};
        t["LPG"]["response"] = LearnEntry{"Tiempo de la cola tras el golpe (~30 ms a 2,5 s) — la \"memoria\" del LDR simulado.", "Sube rápido (~2 ms) siempre; baja despacio y frena cerca de 0 — respuesta asimétrica de vactrol, no una envolvente simétrica común.", ""};
        t["LPG"]["offset"] = LearnEntry{"Apertura de reposo — cuánto queda abierto el LPG incluso sin golpe.", "", ""};
